// El exportador publica ÚNICAMENTE avisos activos en la fecha local México.
// No incluir borradores ni avisos futuros en el JSON que ve el visitante.
const rows = $input.all().map(item => item.json).filter(row => row && row.id);
const formatter = new Intl.DateTimeFormat('en-CA', {
  timeZone: 'America/Mexico_City', year: 'numeric', month: '2-digit', day: '2-digit'
});
const parts = formatter.formatToParts(new Date());
const today = `${parts.find(p => p.type === 'year').value}-${parts.find(p => p.type === 'month').value}-${parts.find(p => p.type === 'day').value}`;
const cleanUrl = (raw) => {
  const value = String(raw || '').trim();
  if (value.startsWith('/') && !value.startsWith('//')) return value;
  try { const u = new URL(value); return ['https:', 'http:'].includes(u.protocol) ? u.toString() : ''; }
  catch { return ''; }
};
const avisos = rows.filter(r => {
  const status = String(r.estado || '').trim().toLowerCase();
  const start = String(r.inicio || '').slice(0,10);
  const end = String(r.fin || '').slice(0,10);
  return status === 'publicado' && (!start || start <= today) && (!end || end >= today);
}).map(r => ({
  id: String(r.id),
  titulo: String(r.titulo || '').slice(0,110),
  resumen: String(r.resumen || '').slice(0,230),
  categoria: String(r.categoria || 'AVISO').slice(0,32),
  imagen: cleanUrl(r.imagen),
  enlace: cleanUrl(r.enlace),
  fecha: String(r.inicio || '').slice(0,10),
  orden: Number(r.orden) || 50
})).filter(r => r.titulo).sort((a,b)=>a.orden-b.orden).slice(0,16);
return [{ json: { actualizado: new Date().toISOString(), avisos } }];
